//! 🧪️ Resident native array storage retains the original allocation through bounded turns.
use semio_framework_value_native_array_backing::NativeArrayBacking;
use semio_framework_value_control_contract::{OriginalEffectReply,OriginalEffectReplyComplete,RetainedAllocationEffect,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,ValueError};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn run(bank:&mut EffectBank,d:RetirementDemand,work:u64,operation:impl for<'r>FnOnce(&mut RetainedAllocationEffect<'_>,OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>)->RetainedCloneProgress{let g=grant(d);let mut reply=None;let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,work,|effect|{let before=effect.performed_work();let complete=operation(effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap();drop(complete);RetainedWorkPoll::Complete(RetainedWorkOutcome{result:reply.take().unwrap(),work:effect.performed_work()-before})}));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native backing did not complete")};let p=turn.result.unwrap().progress();if let Some(bytes)=marker{assert_eq!(bytes,heap.0)}else{assert_eq!(heap.0,0)}assert_eq!(bank.take_admitted(),if turn.work==0{None}else{Some(true)});bank.post(p,g,heap);p}
#[test]fn resident_array_backing_admits_bounded_headers_and_publishes_same_allocation(){let law:serde_json::Value=serde_json::from_str(include_str!("law.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut large=NativeArrayBacking::<u8,8192>::new();let demand=NativeArrayBacking::<u8,8192>::reserve_demand().unwrap();assert!(demand.copy_bytes<=law["maximumCopy"].as_u64().unwrap() as usize);assert_eq!(demand.capacity_bytes,law["large"].as_u64().unwrap() as usize);let denied=run(&mut bank,demand,0,|effect,reply|large.reserve_into(effect,reply));assert_eq!(denied,RetainedCloneProgress::default());assert!(!large.reserved());let birth=run(&mut bank,demand,1,|effect,reply|large.reserve_into(effect,reply));assert_eq!(birth.retained_capacity_bytes,8192);assert!(large.reserved());let denied_release=run(&mut bank,large.release_demand().unwrap(),0,|effect,reply|large.release_into(effect,reply));assert_eq!(denied_release,RetainedCloneProgress::default());assert!(large.reserved());let release=run(&mut bank,large.release_demand().unwrap(),1,|effect,reply|large.release_into(effect,reply));assert_eq!(release.released_bytes,8192);assert!(large.terminal_is_empty());let mut array=NativeArrayBacking::<u64,3>::new();run(&mut bank,NativeArrayBacking::<u64,3>::reserve_demand().unwrap(),1,|effect,reply|array.reserve_into(effect,reply));let pointer=array.as_ptr().unwrap();let mut foreign=EffectBank::new(Wallet::from_profile(&law["stock"]));let before=foreign.wallet().remaining_work();let mut foreign_input=Some(99u64);let mut reply=None;let((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||foreign.run(grant(NativeArrayBacking::<u64,3>::element_demand().unwrap()),1,|effect|{let start=effect.performed_work();assert!(array.push_from(&mut foreign_input,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).is_err());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:effect.performed_work()-start})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));assert_eq!(marker,None);assert_eq!(heap,(0,0));assert_eq!(foreign.take_admitted(),None);assert_eq!(foreign.wallet().remaining_work(),before);assert_eq!(foreign_input,Some(99));assert_eq!(array.as_ptr(),Some(pointer));for value in law["values"].as_array().unwrap(){let mut input=Some(value.as_u64().unwrap());run(&mut bank,NativeArrayBacking::<u64,3>::element_demand().unwrap(),1,|effect,reply|array.push_from(&mut input,effect,reply));assert!(input.is_none())}assert_eq!(array.as_slice().unwrap(),&[2,7,11]);let mut output=None;let denied=run(&mut bank,array.publication_demand().unwrap(),0,|effect,reply|array.publish_into(&mut output,effect,reply));assert_eq!(denied,RetainedCloneProgress::default());assert!(output.is_none());assert_eq!(array.as_ptr(),Some(pointer));run(&mut bank,array.publication_demand().unwrap(),1,|effect,reply|array.publish_into(&mut output,effect,reply));assert!(array.terminal_is_empty());assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(**output.as_ref().unwrap(),[2,7,11]);let d=RetirementDemand{copy_bytes:std::mem::size_of_val(&output),release_bytes:std::mem::size_of::<[u64;3]>(),depth:1,..Default::default()};run(&mut bank,d,1,|effect,reply|{assert!(effect.performed(1)?);drop(output.take());Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))))});assert!(output.is_none());}

#[test]fn zero_sized_backing_does_not_invent_an_allocator_attempt(){let law:serde_json::Value=serde_json::from_str(include_str!("law.json")).unwrap();assert_eq!(law["zst"].as_u64().unwrap(),8193);let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut array=NativeArrayBacking::<(),8193>::new();let d=NativeArrayBacking::<(),8193>::reserve_demand().unwrap();assert_eq!(d.capacity_bytes,0);let p=run(&mut bank,d,1,|effect,reply|array.reserve_into(effect,reply));assert_eq!(p.retained_capacity_bytes,0);let p=run(&mut bank,array.release_demand().unwrap(),1,|effect,reply|array.release_into(effect,reply));assert_eq!(p.released_bytes,0);assert!(array.terminal_is_empty());}

#[test]fn noncopy_element_returns_its_actual_original_pointer(){let law:serde_json::Value=serde_json::from_str(include_str!("law.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&law["stock"]));let mut array=NativeArrayBacking::<String,2>::new();run(&mut bank,NativeArrayBacking::<String,2>::reserve_demand().unwrap(),1,|effect,reply|array.reserve_into(effect,reply));let mut input=Some(law["text"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();let capacity=input.as_ref().unwrap().capacity();run(&mut bank,NativeArrayBacking::<String,2>::element_demand().unwrap(),1,|effect,reply|array.push_from(&mut input,effect,reply));assert!(input.is_none());let mut output=None;run(&mut bank,NativeArrayBacking::<String,2>::element_demand().unwrap(),1,|effect,reply|array.pop_into(&mut output,effect,reply));assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(output.as_deref(),law["text"].as_str());let d=RetirementDemand{copy_bytes:std::mem::size_of_val(&output),release_bytes:capacity,depth:1,..Default::default()};run(&mut bank,d,1,|effect,reply|{assert!(effect.performed(1)?);drop(output.take());Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))))});run(&mut bank,array.release_demand().unwrap(),1,|effect,reply|array.release_into(effect,reply));assert!(array.terminal_is_empty());}

#[test]fn large_copy_uses_bounded_turns_and_exact_finite_work(){let law:serde_json::Value=serde_json::from_str(include_str!("law.json")).unwrap();let chunk=law["chunk"].as_u64().unwrap() as usize;let source=[7u8;8192];let birth=NativeArrayBacking::<u8,8192>::reserve_demand().unwrap();let publication=NativeArrayBacking::<u8,8192>::publication_header_demand().unwrap();let output_clear=std::mem::size_of::<Option<Box<[u8;8192]>>>();let counts:Vec<_>=(0..8192).step_by(chunk).map(|offset|(8192-offset).min(chunk)).collect();let copy=counts.iter().map(|n|NativeArrayBacking::<u8,8192>::copy_demand(*n).unwrap().copy_bytes).sum::<usize>();let work=counts.iter().map(|n|NativeArrayBacking::<u8,8192>::copy_work(*n).unwrap()).sum::<u64>()+3;let stock=RetainedCloneGrant{maximum_items:counts.len()+3,maximum_copy_bytes:birth.copy_bytes+copy+publication.copy_bytes+output_clear,maximum_capacity_bytes:8192,maximum_release_bytes:8192,maximum_depth:8};let mut bank=EffectBank::new(Wallet::new(stock,work));let mut array=NativeArrayBacking::<u8,8192>::new();run(&mut bank,birth,1,|effect,reply|array.reserve_into(effect,reply));let pointer=array.as_ptr().unwrap();let mut offset=0;for count in counts{let d=NativeArrayBacking::<u8,8192>::copy_demand(count).unwrap();let units=NativeArrayBacking::<u8,8192>::copy_work(count).unwrap();assert!(d.copy_bytes<=law["maximumCopy"].as_u64().unwrap() as usize);assert!(units<=4096);run(&mut bank,d,units,|effect,reply|array.copy_from_slice(&source[offset..],count,effect,reply));offset+=count}assert_eq!(offset,source.len());let mut output=None;run(&mut bank,array.publication_demand().unwrap(),1,|effect,reply|array.publish_into(&mut output,effect,reply));assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(&output.as_ref().unwrap()[..],&source);let d=RetirementDemand{copy_bytes:output_clear,release_bytes:8192,depth:1,..Default::default()};run(&mut bank,d,1,|effect,reply|{assert!(effect.performed(1)?);drop(output.take());Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))))});assert_eq!(bank.wallet().remaining_work(),0);}

#[test]fn large_copy_can_be_cancelled_in_bounded_real_work_turns(){let law:serde_json::Value=serde_json::from_str(include_str!("law.json")).unwrap();let chunk=law["chunk"].as_u64().unwrap() as usize;let discard=law["discardChunk"].as_u64().unwrap() as usize;let source=[7u8;8192];let birth=NativeArrayBacking::<u8,8192>::reserve_demand().unwrap();let copies:Vec<_>=(0..8192).step_by(chunk).map(|offset|(8192-offset).min(chunk)).collect();let discards:Vec<_>=(0..8192).step_by(discard).map(|offset|(8192-offset).min(discard)).collect();let copy_bytes=copies.iter().map(|n|NativeArrayBacking::<u8,8192>::copy_demand(*n).unwrap().copy_bytes).sum::<usize>();let discard_bytes=discards.iter().map(|n|NativeArrayBacking::<u8,8192>::discard_demand(*n).unwrap().copy_bytes).sum::<usize>();let release=NativeArrayBacking::<u8,8192>::release_header_demand().unwrap();let work=copies.iter().map(|n|NativeArrayBacking::<u8,8192>::copy_work(*n).unwrap()).sum::<u64>()+discards.iter().map(|n|NativeArrayBacking::<u8,8192>::discard_work(*n).unwrap()).sum::<u64>()+2;let stock=RetainedCloneGrant{maximum_items:copies.len()+discards.len()+2,maximum_copy_bytes:birth.copy_bytes+copy_bytes+discard_bytes+release.copy_bytes,maximum_capacity_bytes:8192,maximum_release_bytes:8192,maximum_depth:8};let mut bank=EffectBank::new(Wallet::new(stock,work));let mut array=NativeArrayBacking::<u8,8192>::new();run(&mut bank,birth,1,|effect,reply|array.reserve_into(effect,reply));let mut offset=0;for count in copies{let d=NativeArrayBacking::<u8,8192>::copy_demand(count).unwrap();let units=NativeArrayBacking::<u8,8192>::copy_work(count).unwrap();run(&mut bank,d,units,|effect,reply|array.copy_from_slice(&source[offset..],count,effect,reply));offset+=count}for count in discards{let d=NativeArrayBacking::<u8,8192>::discard_demand(count).unwrap();let units=NativeArrayBacking::<u8,8192>::discard_work(count).unwrap();assert!(units<=4096);run(&mut bank,d,units,|effect,reply|array.discard_copy(count,effect,reply));}assert!(array.as_slice().unwrap().is_empty());run(&mut bank,array.release_demand().unwrap(),1,|effect,reply|array.release_into(effect,reply));assert!(array.terminal_is_empty());assert_eq!(bank.wallet().remaining_work(),0);}

#[test]fn fixed_registry_backing_initializes_bounded_empty_slots_and_fifo_indices(){let count=64usize;let slots_d=NativeArrayBacking::<Option<Box<u64>>,1024>::reserve_demand().unwrap();let free_d=NativeArrayBacking::<u16,1024>::reserve_demand().unwrap();let fill=NativeArrayBacking::<Option<Box<u64>>,1024>::fill_none_demand(count).unwrap();let indices=NativeArrayBacking::<u16,1024>::fill_indices_demand(count).unwrap();let pop=NativeArrayBacking::<Option<Box<u64>>,1024>::element_demand().unwrap();let discard=NativeArrayBacking::<u16,1024>::discard_demand(count).unwrap();let capacity=slots_d.capacity_bytes+free_d.capacity_bytes;let copy=slots_d.copy_bytes+free_d.copy_bytes+fill.copy_bytes+indices.copy_bytes+count*pop.copy_bytes+discard.copy_bytes+NativeArrayBacking::<Option<Box<u64>>,1024>::release_header_demand().unwrap().copy_bytes+NativeArrayBacking::<u16,1024>::release_header_demand().unwrap().copy_bytes;let work=2+NativeArrayBacking::<Option<Box<u64>>,1024>::fill_none_work(count).unwrap()+NativeArrayBacking::<u16,1024>::fill_indices_work(count).unwrap()+count as u64+NativeArrayBacking::<u16,1024>::discard_work(count).unwrap()+2;let grant=RetainedCloneGrant{maximum_items:count+7,maximum_copy_bytes:copy,maximum_capacity_bytes:capacity,maximum_release_bytes:capacity,maximum_depth:8};let mut bank=EffectBank::new(Wallet::new(grant,work));let mut slots=NativeArrayBacking::<Option<Box<u64>>,1024>::new();let mut free=NativeArrayBacking::<u16,1024>::new();run(&mut bank,slots_d,1,|e,r|slots.reserve_into(e,r));run(&mut bank,free_d,1,|e,r|free.reserve_into(e,r));let denial=run(&mut bank,fill,0,|e,r|slots.fill_none_into(count,e,r));assert_eq!(denial,RetainedCloneProgress::default());assert_eq!(slots.initialized(),0);run(&mut bank,fill,NativeArrayBacking::<Option<Box<u64>>,1024>::fill_none_work(count).unwrap(),|e,r|slots.fill_none_into(count,e,r));run(&mut bank,indices,NativeArrayBacking::<u16,1024>::fill_indices_work(count).unwrap(),|e,r|free.fill_indices_into(count,e,r));assert_eq!(slots.initialized(),count);assert!(slots.as_slice().unwrap().iter().all(Option::is_none));assert_eq!(free.as_slice().unwrap(),&(0..64u16).collect::<Vec<_>>());for _ in 0..count{let mut output=None;run(&mut bank,pop,1,|e,r|slots.pop_into(&mut output,e,r));assert!(matches!(output,Some(None)));}run(&mut bank,discard,NativeArrayBacking::<u16,1024>::discard_work(count).unwrap(),|e,r|free.discard_copy(count,e,r));let d=slots.release_demand().unwrap();run(&mut bank,d,1,|e,r|slots.release_into(e,r));let d=free.release_demand().unwrap();run(&mut bank,d,1,|e,r|free.release_into(e,r));assert!(slots.terminal_is_empty()&&free.terminal_is_empty())}

#[test]fn empty_slot_discard_refuses_a_live_original_without_dropping_it(){let birth=NativeArrayBacking::<Option<Box<u64>>,4>::reserve_demand().unwrap();let item=NativeArrayBacking::<Option<Box<u64>>,4>::element_demand().unwrap();let discard=NativeArrayBacking::<Option<Box<u64>>,4>::discard_none_demand(1).unwrap();let release=NativeArrayBacking::<Option<Box<u64>>,4>::release_header_demand().unwrap();let box_release=RetirementDemand{copy_bytes:std::mem::size_of::<Option<Option<Box<u64>>>>(),release_bytes:std::mem::size_of::<u64>(),depth:1,..Default::default()};let stock=RetainedCloneGrant{maximum_items:5,maximum_copy_bytes:birth.copy_bytes+2*item.copy_bytes+release.copy_bytes+box_release.copy_bytes,maximum_capacity_bytes:birth.capacity_bytes,maximum_release_bytes:release.release_bytes+box_release.release_bytes,maximum_depth:2};let mut bank=EffectBank::new(Wallet::new(stock,4+NativeArrayBacking::<Option<Box<u64>>,4>::discard_none_work(1).unwrap()+1));let mut slots=NativeArrayBacking::<Option<Box<u64>>,4>::new();run(&mut bank,birth,1,|e,r|slots.reserve_into(e,r));let mut input=Some(Some(Box::new(99)));let pointer=input.as_ref().unwrap().as_ref().unwrap().as_ref() as *const u64;run(&mut bank,item,1,|e,r|slots.push_from(&mut input,e,r));let mut reply=None;let grant=grant(discard);let work=NativeArrayBacking::<Option<Box<u64>>,4>::discard_none_work(1).unwrap();let ((poll,marker),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(grant,work,|e|{let before=e.performed_work();drop(slots.discard_none_into(1,e,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok::<_,ValueError>(()),work:e.performed_work()-before})}));assert!(matches!(poll,RetainedWorkPoll::Complete(_)));assert!(reply.take().unwrap().is_err());assert_eq!(marker,None);assert_eq!(heap,(0,0));assert_eq!(slots.initialized(),1);assert_eq!(slots.as_slice().unwrap()[0].as_ref().unwrap().as_ref() as *const u64,pointer);assert_eq!(bank.take_admitted(),Some(true));bank.post(Default::default(),grant,heap);let mut output=None;run(&mut bank,item,1,|e,r|slots.pop_into(&mut output,e,r));run(&mut bank,box_release,1,|e,r|{assert!(e.performed(1)?);drop(output.take());Ok(r.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:box_release.copy_bytes,released_bytes:box_release.release_bytes,..Default::default()}))))});run(&mut bank,release,1,|e,r|slots.release_into(e,r));assert!(slots.terminal_is_empty())}
